from collections import OrderedDict

def cache_trace(capacity, events):
    entries = OrderedDict()
    reads = []
    for event in events:
        now, key = event['t'], event['key']
        for old_key in list(entries):
            if entries[old_key][1] <= now:
                del entries[old_key]
        if event['op'] == 'get':
            reads.append(entries[key][0] if key in entries else None)
            if key in entries:
                entries.move_to_end(key)
        elif event['op'] == 'delete':
            entries.pop(key, None)
        else:
            entries.pop(key, None)
            if event['ttl'] <= 0 or capacity == 0:
                continue
            entries[key] = (event['value'], now + event['ttl'])
            while len(entries) > capacity:
                entries.popitem(last=False)
    return {'reads': reads, 'keys': list(entries)}

